function schedule(key: string, patch: P) {
  const previous = pending.get(key)
  if (previous) clearTimeout(previous.timer)
  pending.set(key, {
    patch: { ...previous?.patch, ...patch } as P,
    timer: setTimeout(() => {
      void run(key)
    }, ms),
  })
}

export function resolveInitialLocale(stored: string | null, navigatorLanguages: readonly string[]): UiLocale {
  if (isUiLocale(stored)) return stored
  for (const lang of navigatorLanguages) {
    const base = lang.split('-')[0]!.toLowerCase()
    if (isUiLocale(base)) return base
  }
  return 'en'
}
